// Build a pillar up to y=85 to reach daddyhot's destination
let p = world.getPosition(bot);
// We are at y=4, need to go up to y=85
while (p.y < 85) {
    let success = await skills.placeBlock(bot, "dirt", p.x, p.y + 2, p.z, 'top');
    if (!success) {
        // try placing without jumping or adjust
        await skills.placeBlock(bot, "dirt", Math.floor(p.x), Math.floor(p.y + 1), Math.floor(p.z), 'top');
    }
    // Jump up
    bot.setControlState('jump', true);
    await skills.wait(bot, 200);
    bot.setControlState('jump', false);
    p = world.getPosition(bot);
    // Safety break if stuck
    if (p.y > 85) break;
}```
